from pathlib import Path
import importlib.util,json,base64
H=Path(__file__).resolve().parent;P=H.parent
sp=importlib.util.spec_from_file_location('dispatch',P/'dispatch.py');d=importlib.util.module_from_spec(sp);sp.loader.exec_module(d)
plan=d.verify();input_root,run_root=d.remote_roots();observe_root=run_root.replace('copycost-run-','copycost-observe-')
# Frozen runner remains unchanged. Separate read-only sampler records ambient CPU/compiler activity.
observer=(H/'observe.ps1').read_text()
# Remote bootstrap saves exact sampler bytes under separate fresh owned root.
encoded=base64.b64encode(observer.encode()).decode()
script=r'''$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$obs='OBS';$run='RUN';if(Test-Path -LiteralPath $obs){throw 'Observer root already exists'};[IO.Directory]::CreateDirectory($obs)|Out-Null;[IO.File]::WriteAllBytes((Join-Path $obs 'observe.ps1'),[Convert]::FromBase64String('SAMPLER'));$tokens=$null;$errors=$null;[Management.Automation.Language.Parser]::ParseFile((Join-Path $obs 'observe.ps1'),[ref]$tokens,[ref]$errors)|Out-Null;if($errors.Count){throw ($errors|Out-String)};$exe='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe';$args=@('-NoProfile','-File',(Join-Path $obs 'observe.ps1'),'-RunRoot',$run,'-ObserverRoot',$obs);$info=[Diagnostics.ProcessStartInfo]::new($exe);$info.Arguments=($args|ForEach-Object {'"'+$_+'"'})-join' ';$info.UseShellExecute=$false;$info.CreateNoWindow=$true;$info.RedirectStandardOutput=$true;$info.RedirectStandardError=$true;$p=[Diagnostics.Process]::Start($info);$start=$p.StartTime.ToUniversalTime().ToString('o');$o=$p.StandardOutput.ReadToEndAsync();$e=$p.StandardError.ReadToEndAsync();[ordered]@{pid=$p.Id;executable=$exe;argv=$args;startedAt=$start;runRoot=$run;observerRoot=$obs;samplerHash=(Get-FileHash -LiteralPath (Join-Path $obs 'observe.ps1')).Hash.ToLowerInvariant()}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $obs 'observer-start.json') -Encoding UTF8;try{$ready=[DateTime]::UtcNow.AddSeconds(30);while(-not(Test-Path -LiteralPath (Join-Path $obs 'samples.jsonl'))){if($p.HasExited -or [DateTime]::UtcNow-ge$ready){throw 'Observer failed before workload'};Start-Sleep -Milliseconds 200};& 'INPUT\run-pair.ps1' -InputRoot 'INPUT' -RunRoot $run -ExecutionToken 'ROOT-CPU-RELEASE-AND-SOURCE-REVIEW-CLEAR'}finally{[IO.File]::WriteAllBytes((Join-Path $obs 'stop-observer'),[byte[]]@());if(-not$p.WaitForExit(20000)){throw 'Observer failed bounded completion; no foreign process touched'};[IO.File]::WriteAllText((Join-Path $obs 'observer.stdout.txt'),$o.GetAwaiter().GetResult(),[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText((Join-Path $obs 'observer.stderr.txt'),$e.GetAwaiter().GetResult(),[Text.UTF8Encoding]::new($false));[ordered]@{pid=$p.Id;exitCode=$p.ExitCode;endedAt=[DateTime]::UtcNow.ToString('o')}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $obs 'observer-end.json') -Encoding UTF8;$p.Dispose()}'''
script=script.replace('OBS',observe_root).replace('RUN',run_root).replace('SAMPLER',encoded).replace('INPUT',input_root)
d.invoke('execution/run-observed-dispatch',d.argv(script),timeout=1900)
